// pages/AboutUsPage/AboutUsPage.jsx
import React, { useState } from 'react';
import Header from '../../components/Header/Header';
import Footer from '../../components/Footer/Footer';
import Breadcrumbs from '../../components/Breadcrumbs/Breadcrumbs';
import HeroSection from '../../components/HeroSection/HeroSection';
import PrinciplesSection from '../../components/PrinciplesSection/PrinciplesSection';
import AudienceSection from '../../components/AudienceSection/AudienceSection';
import ExpertiseForm from '../../components/ExpertiseForm/ExpertiseForm';
import './AboutUsPage.css';

const AboutUsPage = () => {
    const [formData, setFormData] = useState({
        name: '',
        city: '',
        contact_person: '',
        contact_phone: '',
        contact_email: ''
    });

    const [isSubmitting, setIsSubmitting] = useState(false);
    const [submitMessage, setSubmitMessage] = useState('');

    const handleSubmit = async (e) => {
        e.preventDefault();
        setIsSubmitting(true);
        setSubmitMessage('');

        try {
            const response = await fetch('http://localhost:8000/applications', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(formData)
            });
            
            const result = await response.json();
            
            if (response.ok) {
                setSubmitMessage(result.message || 'Заявка успешно отправлена! Мы свяжемся с вами в ближайшее время.');
                setFormData({
                    name: '',
                    city: '',
                    contact_person: '',
                    contact_phone: '',
                    contact_email: ''
                });
                
                setTimeout(() => {
                    setSubmitMessage('');
                }, 5000);
            } else {
                setSubmitMessage(result.detail || 'Ошибка при отправке заявки. Пожалуйста, попробуйте позже.');
            }
        } catch (error) {
            console.error('Error:', error);
            setSubmitMessage('Ошибка соединения. Пожалуйста, проверьте подключение к интернету.');
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="App">
            <Header />
            <main className="main-content">
                <div className="about-us-page">
                    <Breadcrumbs
                        items={[
                            { label: 'Главная', path: '/' },
                            { label: 'О нас', path: null }
                        ]}
                    />
                    
                    <HeroSection />
                    
                    <div className="divider"></div>
                    
                    <PrinciplesSection />
                    
                    <div className="divider"></div>
                    
                    <AudienceSection />
                    
                    <div className="divider"></div>
                    
                    <ExpertiseForm 
                        formData={formData}
                        setFormData={setFormData}
                        handleSubmit={handleSubmit}
                        isSubmitting={isSubmitting}
                        submitMessage={submitMessage}
                    />
                </div>
            </main>
            <Footer />
        </div>
    );
};

export default AboutUsPage;
